import{_ as s,o as n,c as e,a0 as t}from"./chunks/framework.BxCN1dRw.js";const h=JSON.parse('{"title":"Axum SaaS Template —— 以真实应用学习的开源模板","description":"以 Rust + React 为基础构建 SaaS，通过真实可运行的应用学习与扩展。","frontmatter":{"docLocale":"zh","counterpart":"/en/","layout":"page","sidebar":false,"title":"Axum SaaS Template —— 以真实应用学习的开源模板","description":"以 Rust + React 为基础构建 SaaS，通过真实可运行的应用学习与扩展。"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function d(i,a,c,r,o,p){return n(),e("div",null,[...a[0]||(a[0]=[t('<div class="landing"><section class="landing-hero"><p class="landing-eyebrow">开源模板 · MIT 许可证</p><h1>以 Rust + React 为基础构建你的下一个 SaaS</h1><p class="landing-lede"> 通过真实可运行的应用学习与扩展。注册、会话、成员、限流、任务、部署与备份不是路线图上的承诺，而是你现在就能启动、验证并替换的能力。 </p><p class="landing-actions"><a class="landing-button landing-button-primary" href="docs/">查看文档</a><a class="landing-button" href="https://github.com/CaiZongyuan/axum-saas-template">GitHub 仓库</a></p></section><section class="landing-section"><h2 class="landing-heading">使用流程</h2><div class="landing-steps"><a class="landing-step" href="getting-started/quickstart"><span class="landing-step-num">1</span><h3>启动完整技术栈</h3><p>克隆仓库后一条 <code>just dev</code> 拉起 API、worker、Web、PostgreSQL、Redis、RustFS 与 Mailpit。</p></a><a class="landing-step" href="tutorials/first-request"><span class="landing-step-num">2</span><h3>发出第一条全栈请求</h3><p>从真实请求开始跟做教程，每一章都对应可运行的命令与测试入口。</p></a><a class="landing-step" href="tutorials/example-removal"><span class="landing-step-num">3</span><h3>组合或移除参考业务</h3><p>按所有权清单整块移除参考示例，Core 保持原样运行，业务边界有静态检查守护。</p></a><a class="landing-step" href="tutorials/single-machine-production"><span class="landing-step-num">4</span><h3>部署、备份与恢复</h3><p>单机 compose 生产部署与降级验证，配合备份归档与独立环境恢复演练。</p></a></div></section><section class="landing-section"><h2 class="landing-heading">真实能力</h2><p class="landing-section-lede"> 以下能力均已交付，各自带有教程章节、自动化测试与门禁，不是计划项；逐项对照见 <a href="architecture/v1-coverage">v1 覆盖与验收</a>。 </p><div class="landing-grid"><a class="landing-card" href="tutorials/registration"><span class="landing-dot"></span><h3>注册、登录与会话</h3><p>事务化的注册与登录、会话失效与多端管理，对照 API 测试与真实浏览器旅程验证。</p></a><a class="landing-card" href="tutorials/members"><span class="landing-dot dot-green"></span><h3>成员管理与最后 Owner</h3><p>成员角色变更与去激活即时失效会话，最后 Owner 保护防止锁死组织。</p></a><a class="landing-card" href="tutorials/password-reset"><span class="landing-dot dot-amber"></span><h3>密码重置与可靠邮件</h3><p>注册与重置邮件在开发栈由 Mailpit 接收，生产切换真实 SMTP。</p></a><a class="landing-card" href="tutorials/rate-limits"><span class="landing-dot dot-red"></span><h3>请求限流与保守回退</h3><p>Redis 限流与保守回退：缓存不可用时服务照常响应，系统页展示真实状态。</p></a><a class="landing-card" href="tutorials/electron-shell"><span class="landing-dot dot-cyan"></span><h3>Electron 桌面壳</h3><p>同一套 Web 页面进入安全桌面壳，IPC 契约测试与桌面冒烟在 CI 运行。</p></a><a class="landing-card" href="tutorials/single-machine-production"><span class="landing-dot dot-blue"></span><h3>单机生产部署</h3><p>compose 生产栈与降级验证，公开教程覆盖从证书到回退的完整过程。</p></a><a class="landing-card" href="tutorials/backup-restore"><span class="landing-dot dot-green"></span><h3>备份与恢复演练</h3><p>备份归档不含秘密，在独立环境恢复后验证文档、附件与任务。</p></a></div></section><section class="landing-section"><h2 class="landing-heading">参考示例：个人知识库</h2><p class="landing-section-lede"> 一个可整块移除的参考业务，演示业务约束、并发与资源授权如何组合在 Core 之上；边界与移除步骤见 <a href="tutorials/example-removal">组合与移除参考业务</a>。 </p><div class="landing-grid"><a class="landing-card" href="tutorials/personal-documents"><span class="landing-dot"></span><h3>第一篇 Markdown 文档</h3><p>文档的增删改查与正文安全渲染。</p></a><a class="landing-card" href="tutorials/search-preview"><span class="landing-dot dot-cyan"></span><h3>标题搜索与安全预览</h3><p>标题搜索、分页与不执行脚本的预览。</p></a><a class="landing-card" href="tutorials/edit-conflicts"><span class="landing-dot dot-amber"></span><h3>显式保存与版本冲突</h3><p>宽屏双栏实时预览，窄屏页签；并发保存触发 409，冲突处理可理解。</p></a><a class="landing-card" href="tutorials/library-grants"><span class="landing-dot dot-purple"></span><h3>共享知识库与权限继承</h3><p>Reader/Editor 授权、回收与权限继承。</p></a><a class="landing-card" href="tutorials/attachments"><span class="landing-dot dot-green"></span><h3>RustFS 附件</h3><p>附件上传下载走真实对象存储、校验与浏览器 CORS。</p></a><a class="landing-card" href="tutorials/document-exports"><span class="landing-dot dot-red"></span><h3>文档导出与任务</h3><p>ZIP 导出交给 PostgreSQL Jobs，失败可由管理员重试。</p></a><a class="landing-card" href="tutorials/api-keys"><span class="landing-dot dot-purple"></span><h3>API Key 与资源权限</h3><p>签发 API Key 读取其有权访问的知识文档，权限范围可验证。</p></a></div></section><section class="landing-section landing-closing"><h2 class="landing-heading">从文档开始</h2><p class="landing-lede"> 文档教程与模板源码同步演进：每章可跟做、可验证，也能整章替换为你自己的业务。 </p><p class="landing-actions"><a class="landing-button landing-button-primary" href="docs/">查看文档</a><a class="landing-button" href="getting-started/quickstart">快速开始</a></p></section></div><hr><p>源码版本：<code>1983c7865d35</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/1983c7865d35367862324bbe8508822edd1296f6/docs/index.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',3)])])}const u=s(l,[["render",d]]);export{h as __pageData,u as default};
